package kr.or.arte.seal.rights.application;

import kr.or.arte.seal.recipient.crypto.*;import kr.or.arte.seal.retention.application.RetentionJobRequestPort;import kr.or.arte.seal.rights.domain.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;

@Service public class RightsRequestService {
 private final RightsRequestRepository repository;private final PersonalDataCipher cipher;private final RetentionJobRequestPort retention;private final Clock clock;
 public RightsRequestService(RightsRequestRepository r,PersonalDataCipher c,RetentionJobRequestPort p,Clock clock){repository=r;cipher=c;retention=p;this.clock=clock;}
 @Transactional public UUID create(UUID org,UUID recipient,UUID consentRequest,RightsRequestType type,LocalDate received,LocalDate due,String detail,UUID actor){if(due.isBefore(received))throw new IllegalArgumentException("처리기한은 접수일보다 빠를 수 없습니다.");UUID id=UUID.randomUUID();EncryptedValue value=encrypt(id,org,"detail",detail);String code="RR-"+received.format(DateTimeFormatter.BASIC_ISO_DATE)+"-"+id.toString().substring(0,8).toUpperCase();repository.insert(new RightsRequestRecord(id,code,org,recipient,consentRequest,type,RightsRequestStatus.RECEIVED,received,due,value.bytes(),null,null,value.keyId(),null,actor,clock.instant(),null,null,0));repository.insertEvent(id,null,RightsRequestStatus.RECEIVED,actor,null,clock.instant());return id;}
 public List<RightsRequestSummary> search(UUID actor,RightsRequestStatus status){return repository.search(actor,status);}
 public RightsRequestDetail require(UUID actor,UUID id){var r=repository.findScoped(actor,id).orElseThrow(()->new NoSuchElementException("권리요청을 찾을 수 없습니다."));String detail=r.detailCiphertext()==null?"보유기간 만료로 암호화 상세정보가 파기되었습니다.":decrypt(r,"detail",r.detailCiphertext());return new RightsRequestDetail(r,detail,decryptNullable(r,"verificationNote",r.verificationNoteCiphertext()),decryptNullable(r,"resultNote",r.resultNoteCiphertext()));}
 @Transactional public void verifyIdentity(UUID actor,UUID id,String channel,String note){var r=lock(actor,id);RightsRequestStatus to=RightsRequestTransition.next(r.status(),RightsRequestStatus.IDENTITY_VERIFIED);EncryptedValue encrypted=encrypt(id,r.organizationId(),"verificationNote",note);repository.transition(id,r.status(),to,actor,channel,encrypted.bytes(),encrypted.keyId(),null,null,clock.instant(),r.rowVersion());repository.insertEvent(id,r.status(),to,actor,null,clock.instant());}
 @Transactional public void startReview(UUID actor,UUID id){move(actor,id,RightsRequestStatus.IN_REVIEW,null,null);}
 @Transactional public void decide(UUID actor,UUID id,boolean approve,String reason){var r=lock(actor,id);RightsRequestTransition.requireSeparateDecision(r.createdBy(),actor);RightsRequestStatus to=RightsRequestTransition.next(r.status(),approve?RightsRequestStatus.APPROVED:RightsRequestStatus.REJECTED);repository.transition(id,r.status(),to,actor,null,null,r.keyId(),reason,null,clock.instant(),r.rowVersion());repository.insertEvent(id,r.status(),to,actor,reason,clock.instant());}
 @Transactional public void complete(UUID actor,UUID id,String result){var r=lock(actor,id);boolean approved=r.status()==RightsRequestStatus.APPROVED;if(approved&&r.type()==RightsRequestType.ERASURE){if(r.retentionJobId()==null){UUID job=retention.requestUrgent(id,r.consentRequestId(),r.recipientId(),actor,clock.instant());repository.linkRetentionJob(id,job,r.rowVersion());return;}if(!retention.isConfirmed(r.retentionJobId(),actor))throw new IllegalStateException("삭제 작업 확인이 완료된 뒤 권리요청을 완료할 수 있습니다.");}RightsRequestStatus to=RightsRequestTransition.next(r.status(),RightsRequestStatus.COMPLETED);if(approved&&r.type()==RightsRequestType.WITHDRAWAL){UUID response=repository.responseId(r.consentRequestId()).orElseThrow(()->new IllegalStateException("완료 동의 응답이 없습니다."));repository.insertWithdrawal(id,response,actor,clock.instant());}else if(approved&&r.type()==RightsRequestType.RESTRICTION){retention.placeRestrictionHold(r.consentRequestId(),actor,clock.instant());}EncryptedValue encrypted=r.detailCiphertext()==null?null:encrypt(id,r.organizationId(),"resultNote",result);repository.transition(id,r.status(),to,actor,null,null,encrypted==null?null:encrypted.keyId(),null,encrypted==null?null:encrypted.bytes(),clock.instant(),r.rowVersion());repository.insertEvent(id,r.status(),to,actor,null,clock.instant());}
 private void move(UUID actor,UUID id,RightsRequestStatus to,String reason,byte[] result){var r=lock(actor,id);RightsRequestStatus changed=RightsRequestTransition.next(r.status(),to);repository.transition(id,r.status(),changed,actor,null,null,r.keyId(),reason,result,clock.instant(),r.rowVersion());repository.insertEvent(id,r.status(),changed,actor,reason,clock.instant());}
 private RightsRequestRecord lock(UUID actor,UUID id){return repository.findScopedForUpdate(actor,id).orElseThrow(()->new NoSuchElementException("권리요청을 찾을 수 없습니다."));}
 private EncryptedValue encrypt(UUID id,UUID org,String field,String text){if(text==null||text.isBlank())throw new IllegalArgumentException("상세 내용이 필요합니다.");return cipher.encrypt(new PersonalDataContext("RIGHTS_REQUEST",id,org,field),text);}
 private String decrypt(RightsRequestRecord r,String field,byte[] value){return cipher.decrypt(new PersonalDataContext("RIGHTS_REQUEST",r.id(),r.organizationId(),field),new EncryptedValue(r.keyId(),value));}
 private String decryptNullable(RightsRequestRecord r,String field,byte[] value){return value==null?null:decrypt(r,field,value);}
}
